<?php
require 'config.php'; require 'auth.php'; requireLogin(); $pageTitle='Tambah Alat'; $categories=read_data('categories'); $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ $sku=trim($_POST['sku']??'');$name=trim($_POST['name']??'');$cat=(int)($_POST['category_id']??0);$unit=trim($_POST['unit']??'')?:'pcs';$stock=max(0,(int)($_POST['stock']??0));$min=max(0,(int)($_POST['min_stock']??0));$items=read_data('items'); if($sku===''||$name==='')$errors[]='Kode dan nama alat wajib diisi.'; elseif(array_filter($items,fn($i)=>strcasecmp($i['sku'],$sku)===0))$errors[]='Kode alat sudah digunakan.'; else {$id=next_id($items);$items[]=['id'=>$id,'sku'=>$sku,'name'=>$name,'category_id'=>$cat?:null,'unit'=>$unit,'stock'=>$stock,'min_stock'=>$min];write_data('items',$items);if($stock>0)save_transaction($id,'IN',$stock,'Stok awal');$_SESSION['flash']=['type'=>'success','message'=>'Alat berhasil ditambahkan.'];redirect('index.php');}} include 'header.php'; ?>
<section class="page-heading"><div><h1>Tambah Alat Baru</h1><p>Data disimpan langsung ke file TXT (JSON).</p></div></section><div class="form-card"><?php foreach($errors as $x):?><div class="alert alert-error"><?=e($x)?></div><?php endforeach;?><form method="post"><div class="form-group"><label>Kode Alat</label><input name="sku" value="<?=e($_POST['sku']??'')?>" required></div><div class="form-group"><label>Nama Alat</label><input name="name" value="<?=e($_POST['name']??'')?>" required></div><div class="form-group"><label>Kategori</label><select name="category_id"><option value="">Tanpa kategori</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Satuan</label><input name="unit" list="unit-list" value="<?=e($_POST['unit']??'pcs')?>" placeholder="Pilih atau ketik satuan baru"><datalist id="unit-list"><option value="pcs"><option value="meter"><option value="box"><option value="roll"><option value="pack"><option value="unit"><option value="set"></datalist></div><div class="form-group"><label>Stok Awal</label><input type="number" name="stock" min="0" value="<?=e($_POST['stock']??0)?>"></div><div class="form-group"><label>Batas Stok Menipis</label><input type="number" name="min_stock" min="0" value="<?=e($_POST['min_stock']??2)?>"></div><div class="form-actions"><button class="btn btn-primary">Simpan</button><a class="btn btn-secondary" href="index.php">Batal</a></div></form></div><?php include 'footer.php'; ?>